(function ($) {
  "use strict";

  // ── Format switcher ──────────────────────────────────────────────
  $('body').on('change', '.js-question-format-select', function () {
    var $form = $(this).closest('form');
    var format = $(this).val();

    // hide all format areas
    $form.find('[class*="js-format-area-"]').addClass('d-none');
    // show the selected one
    $form.find('.js-format-area-' + format).removeClass('d-none');

    // Show "Create Table" button only for table_completion
    if (format === 'table_completion') {
      $form.find('.js-create-table-btn').removeClass('d-none');
    } else {
      $form.find('.js-create-table-btn').addClass('d-none');
    }
  });

  // ── Show / hide instruction textarea ────────────────────────────
  $('body').on('click', '.js-show-instruction-btn', function () {
    var $form = $(this).closest('form');
    $form.find('.js-instruction-area').toggleClass('d-none');
  });

  // ── Add text block ───────────────────────────────────────────────
  $('body').on('click', '.js-add-text-block', function () {
    var $container = $(this).siblings('.js-text-blocks-container');
    var $newRow = $('<div class="d-flex align-items-start gap-8 mb-8 js-text-block-row">' + '<textarea name="text_blocks[]" rows="2" class="form-control font-13 flex-grow-1" ' + 'placeholder="' + (window.exerciseLang ? window.exerciseLang.text_block_placeholder : 'Line of text — wrap **word** for blanks') + '"></textarea>' + '<button type="button" class="btn btn-sm btn-outline-danger px-8 py-6 rounded-8 js-remove-text-block mt-2">' + '<i class="fa fa-trash"></i></button>' + '</div>');
    $container.append($newRow);
  });

  // ── Remove text block ────────────────────────────────────────────
  $('body').on('click', '.js-remove-text-block', function () {
    $(this).closest('.js-text-block-row').remove();
  });

  // ── Add option (MCQ / single) ────────────────────────────────────
  $('body').on('click', '.js-add-option', function () {
    var $area = $(this).closest('[class*="js-format-area-"]');
    var $container = $area.find('.js-options-container');
    var isSingle = $area.hasClass('js-format-area-single_choice');
    var count = $container.find('.js-option-row').length;
    var letter = String.fromCharCode(65 + count); // A, B, C ...

    var inputType = isSingle ? 'radio' : 'checkbox';
    var radioName = isSingle ? 'name="single_correct_tmp"' : '';
    var $newRow = $('<div class="d-flex align-items-center gap-8 mb-8 js-option-row">' + '<input type="' + inputType + '" ' + radioName + ' class="js-option-correct" style="width:18px;height:18px;cursor:pointer;">' + '<input type="text" name="answer_options[]" class="form-control js-option-text font-13" placeholder="' + (window.exerciseLang ? window.exerciseLang.option : 'Option') + ' ' + letter + '">' + '<button type="button" class="btn btn-sm btn-outline-danger px-8 py-6 rounded-8 js-remove-option">' + '<i class="fa fa-trash"></i></button>' + '</div>');
    $container.append($newRow);
  });

  // ── Remove option ────────────────────────────────────────────────
  $('body').on('click', '.js-remove-option', function () {
    $(this).closest('.js-option-row').remove();
  });

  // ── Generate table grid ──────────────────────────────────────────
  $('body').on('click', '.js-generate-table', function () {
    var $area = $(this).closest('.js-format-area-table_completion');
    var rows = parseInt($area.find('.js-table-rows').val(), 10) || 2;
    var cols = parseInt($area.find('.js-table-cols').val(), 10) || 3;
    var $grid = $area.find('.js-table-grid');
    rows = Math.min(rows, 20);
    cols = Math.min(cols, 10);
    var html = '<table class="table table-sm table-bordered font-13 js-table-input-grid" ' + 'data-rows="' + rows + '" data-cols="' + cols + '">';
    for (var r = 0; r < rows; r++) {
      html += '<tr>';
      for (var c = 0; c < cols; c++) {
        html += '<td class="p-4">' + '<input type="text" class="form-control form-control-sm js-table-cell font-12" ' + 'data-row="' + r + '" data-col="' + c + '" ' + 'placeholder="r' + (r + 1) + 'c' + (c + 1) + '" style="min-width:80px;">' + '</td>';
      }
      html += '</tr>';
    }
    html += '</table>';
    $grid.html(html);
  });

  // ── Sync correct_answers & table_data before submit ─────────────
  $('body').on('submit', '.js-exercise-question-form', function (e) {
    var $form = $(this);
    var format = $form.find('.js-question-format-select').val();

    // Remove old hidden inputs
    $form.find('.js-auto-correct-hidden').remove();
    if (format === 'multiple_choice' || format === 'single_choice') {
      $form.find('.js-option-row').each(function () {
        var $input = $(this).find('.js-option-correct');
        if ($input.is(':checked')) {
          var text = $(this).find('.js-option-text').val().trim();
          if (text) {
            $form.append($('<input type="hidden" name="correct_answers[]" class="js-auto-correct-hidden">').val(text));
          }
        }
      });
    }
    if (format === 'table_completion') {
      var $table = $form.find('.js-table-input-grid');
      if ($table.length) {
        var rows = parseInt($table.data('rows'), 10);
        var cols = parseInt($table.data('cols'), 10);
        var grid = [];
        for (var r = 0; r < rows; r++) {
          var row = [];
          for (var c = 0; c < cols; c++) {
            row.push($table.find('[data-row="' + r + '"][data-col="' + c + '"]').val() || '');
          }
          grid.push(row);
        }
        $form.find('.js-table-data-input').val(JSON.stringify(grid));
      }
    }
  });

  // ── Custom file input label updater ─────────────────────────────
  $('body').on('change', '.js-custom-file-input', function () {
    var fileName = this.files[0] ? this.files[0].name : '';
    $(this).siblings('label').text(fileName || $(this).siblings('label').data('default') || 'Browse');
  });
})(jQuery);
